#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> dp(n + 1, 1e9);
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        int temp = i;
        while (temp > 0) {
            int d = temp % 10;
            if (d > 0) {
                dp[i] = min(dp[i], dp[i - d] + 1);
            }
            temp /= 10;
        }
    }

    cout << dp[n] << "\n";

    return 0;
}
